<script setup lang="ts">
import {computed,ref} from 'vue';
import {preview,type RogueConfig} from './editor-model';
const props=defineProps<{config:RogueConfig}>();
const hp=ref(10000),dps=ref(100),players=ref(1),layer=ref(1);
const rows=computed(()=>Array.from({length:Math.min(200,props.config.pools.at(-1)?.to??30)},(_,i)=>{try{const c=preview(props.config,i+1,players.value,true)[0];return c?{layer:i+1,hp:c.hpMul,damage:c.dmgMul,monsters:c.monsters.length,label:c.label}:null;}catch{return null;}}).filter((x):x is NonNullable<typeof x>=>!!x));
const max=computed(()=>Math.max(1,...rows.value.flatMap(r=>[r.hp,r.damage])));
const line=(key:'hp'|'damage')=>rows.value.map((r,i)=>`${40+i/Math.max(1,rows.value.length-1)*640},${210-r[key]/max.value*175}`).join(' ');
const cursorX=computed(()=>40+(layer.value-1)/Math.max(1,(rows.value.at(-1)?.layer??1)-1)*640);
function selectLayer(e:PointerEvent){const svg=e.currentTarget as SVGSVGElement;const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const matrix=svg.getScreenCTM();if(!matrix)return;const x=point.matrixTransform(matrix.inverse()).x;layer.value=Math.round(Math.max(0,Math.min(1,(x-40)/640))*Math.max(0,(rows.value.at(-1)?.layer??1)-1))+1;if(e.type==='pointerdown')svg.setPointerCapture(e.pointerId);}
const current=computed(()=>rows.value.find(r=>r.layer===layer.value));
</script>
<template><section class="subpanel curve"><h3>难度与攻略耗时估算</h3><div class="toolbar"><label>基准单怪血量<input v-model.number="hp" type="number" min="1"></label><label>队伍有效秒伤<input v-model.number="dps" type="number" min="1"></label><label>人数<select v-model.number="players"><option :value="1">1 人</option><option :value="2">2 人</option><option :value="4">4 人</option></select></label></div><p class="muted">按游戏生成公式、固定种子及全部极强怪解锁绘制每层首个选项；最多展示 200 层。基准血量与有效秒伤为策划假设，耗时仅计算输出时间，不含移动、换区与整备。伤害倍率作为危险程度参考。</p><svg viewBox="0 0 720 250" role="slider" tabindex="0" aria-label="曲线查看层数" :aria-valuenow="layer" :aria-valuemin="1" :aria-valuemax="rows.at(-1)?.layer??1" @pointerdown="selectLayer" @pointermove="$event.buttons===1 && selectLayer($event)" @keydown.left.prevent="layer=Math.max(1,layer-1)" @keydown.right.prevent="layer=Math.min(rows.at(-1)?.layer??1,layer+1)"><path d="M40 25V210H680" fill="none" stroke="#786b54"/><text x="8" y="25">{{ max.toFixed(2) }}</text><text x="18" y="214">0</text><text x="40" y="238">第 1 层</text><text x="610" y="238">第 {{ rows.at(-1)?.layer }} 层</text><polyline :points="line('hp')" fill="none" stroke="#e9bd68" stroke-width="3"/><polyline :points="line('damage')" fill="none" stroke="#91bcba" stroke-width="3"/><line :x1="cursorX" :x2="cursorX" y1="25" y2="210" stroke="#fff0cd" stroke-dasharray="4 3"/><circle :cx="cursorX" cy="210" r="6" fill="#fff0cd"/><text :x="Math.min(cursorX+8,620)" y="18">第 {{ layer }} 层</text></svg><p>金色：每只生命倍率 · 青色：伤害倍率</p><div v-if="current" class="metrics"><span>{{ current.label }}<br>生命 ×{{ current.hp.toFixed(2) }} · 伤害 ×{{ current.damage.toFixed(2) }}<br>估算每只 {{ Math.round(Math.max(0,hp)*current.hp).toLocaleString() }} HP · 本波输出时间 {{ (Math.max(0,hp)*current.hp*current.monsters/Math.max(1,dps)/60).toFixed(1) }} 分钟</span></div></section></template>
<style scoped>.curve svg{touch-action:none;cursor:crosshair;width:100%;max-height:270px}.curve text{fill:#b6a995;font-size:12px}.curve label{display:grid;gap:6px}.curve input{max-width:180px}.curve input[type=range]{max-width:none;width:100%}.metrics{margin:12px 0}</style>
